mapper.select:
SELECT id, connection_id, user_public_id, credential_type, ciphertext,
       key_version, masked_hint, status, created_at, revoked_at
FROM provider_credentials
WHERE connection_id = #{connectionId}
  AND user_public_id = #{userPublicId}
  AND status <> 'REVOKED'

SELECT id, connection_id, user_public_id, credential_type, ciphertext,
       key_version, masked_hint, status, created_at, revoked_at
FROM provider_credentials
WHERE id = #{id}
  AND user_public_id = #{userPublicId}
  AND status <> 'REVOKED'

mapper.update:
UPDATE provider_credentials
SET status = 'VERIFIED'
WHERE id = #{id}
  AND user_public_id = #{userPublicId}
  AND status <> 'REVOKED'

UPDATE provider_credentials
SET status = 'INVALID'
WHERE id = #{id}
  AND user_public_id = #{userPublicId}
  AND status <> 'REVOKED'

UPDATE provider_credentials
SET status = 'REVOKED',
    revoked_at = #{revokedAt}
WHERE connection_id = #{connectionId}
  AND user_public_id = #{userPublicId}
  AND status <> 'REVOKED'
